    function ConfirmDifficulty()

        DestroyTimer(CountdownTimer)
        BlzFrameSetVisible(MainPanelFrame, false)
        ShowQuestAlert(LOCALE_LIST[my_locale].DIFFICULTY_PICKED .. DifficultyDescriptionEx[CurrentDifficulty])
        SetDifficultyBannerIcon()

            if CurrentDifficulty == DIFFICULTY_NIGHTMARE then
                GLOBAL_GOLD_RATE = GLOBAL_GOLD_RATE + 0.1
                WIN_WAVE = 55

                    for i = 1, 6 do
                        if PlayerHero[i] then
                            ModifyStat(PlayerHero[i], ALL_RESIST, -10, true, STRAIGHT_BONUS)
                        elseif IsPlayerSlotState(Player(i-1), PLAYER_SLOT_STATE_PLAYING) then
                            local timer = CreateTimer()
                            local pn = i

                                TimerStart(timer, 1, true, function()
                                    if PlayerHero[pn] then
                                        ModifyStat(PlayerHero[pn], ALL_RESIST, -10, true, STRAIGHT_BONUS)
                                        DestroyTimer(timer)
                                    end
                                end)

                        end
                    end

            elseif CurrentDifficulty == DIFFICULTY_HELL then
                GLOBAL_GOLD_RATE = GLOBAL_GOLD_RATE + 0.2
                GLOBAL_EXP_RATE = GLOBAL_EXP_RATE + 0.1
                GLOBAL_DROP_RATE = GLOBAL_DROP_RATE + 0.1
                WIN_WAVE = 60
                RESET_SHOP_INDEX = 2

                    for i = 1, 6 do
                        if PlayerHero[i] then
                            ModifyStat(PlayerHero[i], ALL_RESIST, -20, true, STRAIGHT_BONUS)
                        elseif IsPlayerSlotState(Player(i-1), PLAYER_SLOT_STATE_PLAYING) then
                            local timer = CreateTimer()
                            local pn = i

                                TimerStart(timer, 1, true, function()
                                    if PlayerHero[pn] then
                                        ModifyStat(PlayerHero[pn], ALL_RESIST, -20, true, STRAIGHT_BONUS)
                                        DestroyTimer(timer)
                                    end
                                end)

                        end
                    end

            end

    end

    function StartDifficultyPick()
        local timeout = 29.
        CountdownTimer = CreateTimer()

            for i = 1, 6 do
                if IsPlayerSlotState(Player(i-1), PLAYER_SLOT_STATE_PLAYING) then
                    OpenDifficultyPickPanel(i-1)
                    break
                end
            end

        TimerStart(CountdownTimer, 1., true, function()

            if timeout <= 0 then
                ConfirmDifficulty()
            else
                timeout = timeout - 1
                BlzFrameSetText(CountdownTextFrame, I2S(math.floor(timeout)))
            end

        end)
    end


